class Solution:
    def getPermutationIndex(self, perm: list[int]) -> int:
        MOD = 10**9 + 7
        n = len(perm)
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = (fact[i - 1] * i) % MOD

        bit = [0] * (n + 2)

        def add(idx, val):
            while idx <= n + 1:
                bit[idx] += val
                idx += idx & (-idx)

        def query(idx):
            s = 0
            while idx > 0:
                s += bit[idx]
                idx -= idx & (-idx)
            return s

        ans = 0
        for i, x in enumerate(perm):
            smaller_seen = query(x)
            smaller_available = (x - 1) - smaller_seen
            rem = n - 1 - i
            ans = (ans + smaller_available * fact[rem]) % MOD
            add(x, 1)
        return ans

class Solution {
public:
    int getPermutationIndex(vector<int>& perm) {
        long long MOD = 1e9 + 7;
        int n = perm.size();
        vector<long long> fact(n + 1, 1);
        for (int i = 1; i <= n; ++i) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }

        vector<int> bit(n + 2, 0);
        auto add = [&](int idx, int val) {
            for (; idx <= n + 1; idx += idx & -idx) bit[idx] += val;
        };
        auto query = [&](int idx) {
            int s = 0;
            for (; idx > 0; idx -= idx & -idx) s += bit[idx];
            return s;
        };

        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            int x = perm[i];
            int smaller_seen = query(x);
            int smaller_available = (x - 1) - smaller_seen;
            int rem = n - 1 - i;
            ans = (ans + 1LL * smaller_available * fact[rem]) % MOD;
            add(x, 1);
        }
        return ans;
    }
};

class Solution {
    public int getPermutationIndex(int[] perm) {
        long MOD = 1_000_000_007L;
        int n = perm.length;
        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }

        int[] bit = new int[n + 2];
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int x = perm[i];
            int smallerSeen = 0;
            for (int idx = x; idx > 0; idx -= idx & -idx) smallerSeen += bit[idx];
            int smallerAvailable = (x - 1) - smallerSeen;
            int rem = n - 1 - i;
            ans = (ans + smallerAvailable * fact[rem]) % MOD;
            for (int idx = x; idx <= n + 1; idx += idx & -idx) bit[idx] += 1;
        }
        return (int) ans;
    }
}

var getPermutationIndex = function(perm) {
    const MOD = 1000000007n;
    const n = perm.length;
    const fact = new Array(n + 1);
    fact[0] = 1n;
    for (let i = 1; i <= n; i++) {
        fact[i] = (fact[i - 1] * BigInt(i)) % MOD;
    }

    const bit = new Array(n + 2).fill(0);
    function add(idx, val) {
        for (; idx <= n + 1; idx += idx & -idx) bit[idx] += val;
    }
    function query(idx) {
        let s = 0;
        for (; idx > 0; idx -= idx & -idx) s += bit[idx];
        return s;
    }

    let ans = 0n;
    for (let i = 0; i < n; i++) {
        const x = perm[i];
        const smallerSeen = query(x);
        const smallerAvailable = BigInt((x - 1) - smallerSeen);
        const rem = n - 1 - i;
        ans = (ans + smallerAvailable * fact[rem]) % MOD;
        add(x, 1);
    }
    return Number(ans);
};
